      "label": "(64)",
      "latex": "h_{\\text{эф}\\Sigma} = h_{n}\\,(1-\\chi_{cn})",
      "meaning": "Суммарная эффективная толщина коллектора в пачке получается из общей толщины пачки и доли глины.",
      "variables": [
        {"symbol": "h_эф Σ", "meaning": "суммарная эффективная толщина продуктивного коллектора в пачке", "unit": "м"},
        {"symbol": "h_n", "meaning": "общая толщина пачки (по смыслу формулы)", "unit": "м"},
        {"symbol": "χ_cn", "meaning": "относительная по толщине глинистость пачки", "unit": "безразмерная"}
      ]
