    ],
    "breaks": [
      {"text": "Отдельные тонкие прослои не выделяются, поэтому отбивку по ним не сделать. Нужен расчёт по всей пачке.", "claims": ["c1", "c2"], "hypothesis": false},
      {"text": "Ошибка в ρ_cn или ρ_nm переходит в χ_cn и в толщину.", "claims": [], "hypothesis": true},
      {"text": "Одинаковое ρ_n может соответствовать разным χ_cn при разных ρ_cn и ρ_nm.", "claims": [], "hypothesis": true}
